import {SpessaSynthProcessor,SoundBankLoader,SpessaLog} from './vendor/spessasynth-core.js';
import {Clock} from './model.js';
SpessaLog.info=()=>{};SpessaLog.group=()=>{};SpessaLog.groupEnd=()=>{};
class CircuitProcessor extends AudioWorkletProcessor{
 constructor(options){super();const o=options.processorOptions;this.p=o.project;this.clock=new Clock(this.p);this.synth=new SpessaSynthProcessor(sampleRate,{effectsEnabled:false,eventsEnabled:false,maxBufferSize:128});this.synth.soundBankManager.addSoundBank(SoundBankLoader.fromArrayBuffer(o.soundfont),'generaluser');this.synth.setSystemParameter('voiceCap',160);this.synth.midiChannels[4].setDrums(true);this.patchKeys=[];this.programs();this.running=!!o.autoplay;this.offline=!!o.offline;this.endFrame=o.duration?Math.round(o.duration*sampleRate):Infinity;this.frames=0;this.queue=[];this.phase=0;this.freq=55;this.targetFreq=55;this.amp=0;this.bassHeld=false;this.bassId=0;this.msgFrames=0;this.fxL=new Float32Array(128);this.fxR=new Float32Array(128);
 this.port.onmessage=({data:d})=>{try{if(d.type==='start'){this.clear();this.clock=new Clock(d.project);this.p=d.project;this.programs();this.running=true;this.frames=0;this.endFrame=Infinity;}else if(d.type==='stop'){this.running=false;this.clear();this.clock.reset();this.port.postMessage({type:'position',positions:[-1,-1,-1,-1,-1,-1],beat:0,pattern:this.clock.pattern});}else if(d.type==='state'){this.p=d.project;this.clock.update(this.p);if(!this.running)this.clock.reset();this.programs();}else if(d.type==='pattern'){if(this.running)this.clock.queue(d.index);else{this.clock.pattern=d.index;this.programs();}}else if(d.type==='preview'){this.note({ch:d.ch,note:d.note,velocity:d.velocity??85,source:d.source||'soundfont',duration:.35,slide:0,accent:0},this.synth.currentTime*sampleRate);}else if(d.type==='panic'){this.clear();}}catch(e){this.port.postMessage({type:'error',message:e.message});}};
 this.port.postMessage({type:'ready'});}
 programs(){const p=this.p.patterns[this.clock.pattern];const tracks=[...p.tracks,{program:p.drums.kit,bank:0},p.bass];tracks.forEach((t,ch)=>{const key=`${t.bank}:${t.program}`;if(this.patchKeys[ch]!==key){this.synth.controllerChange(ch,0,t.bank||0);this.synth.controllerChange(ch,32,0);this.synth.programChange(ch,t.program);this.patchKeys[ch]=key;}this.synth.controllerChange(ch,7,100);this.synth.controllerChange(ch,10,64);this.synth.controllerChange(ch,91,0);this.synth.controllerChange(ch,93,0);});}
 clear(){this.queue=[];this.synth.stopAllChannels(true);this.bassHeld=false;this.amp=0;this.bassId++;}
 note(e,frame){if(e.ch===5&&e.source==='analog'){this.bassId++;this.targetFreq=440*2**((e.note-69)/12);if(!e.slide)this.freq=this.targetFreq;this.amp=(e.velocity/127)*.28*(1+e.accent*(e.velocity>95?.5:0));this.bassHeld=true;this.queue.push({kind:'bassOff',frame:frame+e.duration*sampleRate,id:this.bassId});}else{this.synth.noteOn(e.ch,e.note,e.velocity);this.queue.push({kind:'off',ch:e.ch,note:e.note,frame:frame+e.duration*sampleRate});}}
 render(out,offset,n){if(!n)return;this.synth.processSplit(out,this.fxL,this.fxR,offset,n);const bass=this.p.patterns[this.clock.pattern].bass;const decay=Math.exp(-1/(sampleRate*Math.max(.08,bass.decay)));const glide=bass.slide>0?1-Math.exp(-1/(sampleRate*(.008+bass.slide*.4))):1;for(let i=offset;i<offset+n;i++){this.freq+=(this.targetFreq-this.freq)*glide;this.phase=(this.phase+this.freq/sampleRate)%1;let wave=Math.sin(this.phase*Math.PI*2);if(bass.wave==='triangle')wave=2/Math.PI*Math.asin(wave);if(bass.wave==='saw'){const dt=this.freq/sampleRate;let blep=0;if(this.phase<dt){const t=this.phase/dt;blep=t+t-t*t-1;}else if(this.phase>1-dt){const t=(this.phase-1)/dt;blep=t*t+t+t+1;}wave=2*this.phase-1-blep;}if(!this.bassHeld)this.amp*=.997;else this.amp*=decay;out[5][0][i]+=wave*this.amp;out[5][1][i]+=wave*this.amp;}}
 process(inputs,out){try{const size=out[0][0].length,start=Math.round(this.synth.currentTime*sampleRate);if(this.running){const allowed=Math.min(size,Math.max(0,this.endFrame-this.frames));if(allowed){const ev=this.clock.process(allowed/sampleRate);for(const e of ev)this.queue.push({...e,frame:start+Math.round(e.time*sampleRate)});}this.frames+=size;if(this.frames>=this.endFrame){this.running=false;this.queue.push({kind:'release',frame:start+allowed});}}
 this.queue.sort((a,b)=>a.frame-b.frame);let offset=0;while(this.queue.length&&this.queue[0].frame<start+size){const e=this.queue.shift();const at=Math.max(offset,Math.min(size,Math.round(e.frame-start)));this.render(out,offset,at-offset);offset=at;if(e.kind==='note')this.note(e,e.frame);else if(e.kind==='off')this.synth.noteOff(e.ch,e.note);else if(e.kind==='bassOff'&&e.id===this.bassId)this.bassHeld=false;else if(e.kind==='pattern'){this.programs();if(!this.offline)this.port.postMessage({type:'pattern',index:e.pattern});}else if(e.kind==='release'){this.synth.stopAllChannels(false);this.bassHeld=false;}this.queue.sort((a,b)=>a.frame-b.frame);}
 this.render(out,offset,size-offset);this.msgFrames+=size;if(!this.offline&&this.msgFrames>=sampleRate/30){this.msgFrames=0;this.port.postMessage({type:'position',positions:this.running?this.clock.positions:[-1,-1,-1,-1,-1,-1],beat:this.clock.beat,pattern:this.clock.pattern,voices:this.synth.voiceCount});}return true;}catch(e){this.port.postMessage({type:'error',message:e.message});return false;}}
}
registerProcessor('circuit-synth',CircuitProcessor);
